using ScenarioRuleLibrary;
int assertions=0;void Check(bool value,string what){assertions++;if(!value)throw new Exception(what);}
for(int target=0;target<2;target++)for(int first=0;first<2;first++) {
 var a=new CAbilityCard{Name="old-a"};var b=new CAbilityCard{Name="old-b"};var c=new CAbilityCard{Name="incoming"};var actor=new CPlayerActor();actor.CharacterClass.RoundAbilityCards.AddRange(new[]{a,b});actor.CharacterClass.HandAbilityCards.Add(c);actor.CharacterClass.InitiativeAbilityCard=first==0?a:b;
 var hand=new CardsHandUI{PlayerActor=actor};var factory=new VRCardFactory();var cards=new[]{a,b,c}.Select(x=>{var w=new AbilityCardUI{AbilityCard=x,PlayerActor=actor};hand.cardsUI.Add(w);return factory.GetOrCreate(w);}).ToArray();
 var tray=new PlayTray();tray.PlaceCard(cards[0],0);tray.PlaceCard(cards[1],1);var displaced=cards[target];tray.RemoveCard(displaced);tray.PlaceCard(cards[2],target);var token=tray.BeginPendingSelection(cards[2]);var driver=new CardsDriver(hand,tray,factory);
 actor.CharacterClass.RoundAbilityCards.Remove(displaced.GameCard!.AbilityCard!);actor.CharacterClass.HandAbilityCards.Add(displaced.GameCard.AbilityCard!);actor.CharacterClass.InitiativeAbilityCard=actor.CharacterClass.RoundAbilityCards[0];
 var fan=driver.Fill();tray.SyncFromGameState(hand,factory);driver.MountFan();
 Check(tray.At(target)==cards[2],"pending replacement remains the physical occupant between native callbacks");Check(!fan.Contains(cards[2]),"pending replacement cannot also enter fan");Check(cards[2].Home==target,"pending replacement keeps its real slot home");Check(tray.OccupiedSlotMask==3,"both physical occupied bits remain stable between native callbacks");Check(tray.PendingCount==1,"pending state is bounded to this occupant");
 actor.CharacterClass.HandAbilityCards.Remove(c);actor.CharacterClass.RoundAbilityCards.Add(c);Check(tray.CompletePendingSelection(cards[2],token),"own token completion is accepted");tray.SyncFromGameState(hand,factory);Check(tray.At(target)==cards[2]&&tray.PendingCount==0,"successful own ack keeps incoming visual and clears marker");
 // The same marker must not hide authoritative refusal, actor/phase changes or clear/reset.
 tray.RemoveCard(cards[2]);actor.CharacterClass.RoundAbilityCards.Remove(c);actor.CharacterClass.HandAbilityCards.Add(c);tray.PlaceCard(cards[2],target);var refused=tray.BeginPendingSelection(cards[2]);tray.CompletePendingSelection(cards[2],refused);tray.SyncFromGameState(hand,factory);Check(tray.At(target)!=cards[2]&&tray.PendingCount==0,"refused own ack permits authoritative rollback");
 foreach(var stop in new[]{"phase","mode","confirmed","actor","remove","clear","cancel"}) {
  tray.PlaceCard(cards[2],target);tray.BeginPendingSelection(cards[2]);hand.Phase=true;hand.Mode=CardHandMode.CardsSelection;hand.Confirmed=false;
  if(stop=="phase")hand.Phase=false;if(stop=="mode")hand.Mode=CardHandMode.Preview;if(stop=="confirmed")hand.Confirmed=true;
  if(stop=="actor"){var foreign=new CardsHandUI{PlayerActor=new CPlayerActor()};tray.SyncFromGameState(foreign,factory);}else if(stop=="remove")tray.RemoveCard(cards[2]);else if(stop=="clear")tray.ClearSlots();else if(stop=="cancel"){tray.CancelPendingSelections();tray.SyncFromGameState(hand,factory);}else tray.SyncFromGameState(hand,factory);
  Check(tray.PendingCount==0,stop+" retires pending presentation");hand.Phase=true;hand.Mode=CardHandMode.CardsSelection;hand.Confirmed=false;
 }
 for(int i=0;i<100;i++){tray.RemoveCard(cards[2]);tray.PlaceCard(cards[2],target);tray.BeginPendingSelection(cards[2]);Check(tray.PendingCount<=2,"rapid repeat remains bounded to current occupants");}tray.ClearSlots();Check(tray.PendingCount==0,"final reset releases all markers");
}
// Same-card replacement owns a new token; the old native ack cannot release it.
var raceActor=new CPlayerActor();var raceModel=new CAbilityCard{Name="race"};var raceWidget=new AbilityCardUI{AbilityCard=raceModel,PlayerActor=raceActor};var raceHand=new CardsHandUI{PlayerActor=raceActor};raceHand.cardsUI.Add(raceWidget);var raceFactory=new VRCardFactory();var raceCard=raceFactory.GetOrCreate(raceWidget);var raceTray=new PlayTray();raceTray.PlaceCard(raceCard,0);var oldToken=raceTray.BeginPendingSelection(raceCard);raceTray.WithdrawPendingSelection(raceCard);raceTray.RemoveCard(raceCard);raceTray.PlaceCard(raceCard,1);var newToken=raceTray.BeginPendingSelection(raceCard);Check(!raceTray.CompletePendingSelection(raceCard,oldToken),"stale same-card native ack cannot clear a newer placement token");raceTray.SyncFromGameState(raceHand,raceFactory);Check(raceTray.At(1)==raceCard&&raceTray.PendingCount==1,"later native unselect cannot evict newest pending placement");Check(raceTray.CompletePendingSelection(raceCard,newToken),"newest same-card token owns its completion");raceTray.CancelPendingSelections();
// Explicit take-back supersedes only that captured queued native select.
raceTray.PlaceCard(raceCard,0);var withdrawalToken=raceTray.BeginPendingSelection(raceCard);raceTray.WithdrawPendingSelection(raceCard);raceTray.RemoveCard(raceCard);Check(raceTray.SelectionWasWithdrawn(withdrawalToken),"only explicit user withdrawal supersedes captured select");if(!raceTray.SelectionWasWithdrawn(withdrawalToken))raceActor.CharacterClass.RoundAbilityCards.Add(raceModel);raceTray.CompletePendingSelection(raceCard,withdrawalToken);raceTray.SyncFromGameState(raceHand,raceFactory);Check(raceTray.SlotOf(raceCard)<0,"withdrawal before native ack cannot re-seat the withdrawn surface");
// Releasing a view never supersedes captured native input for the old actor.
raceTray.PlaceCard(raceCard,0);var viewToken=raceTray.BeginPendingSelection(raceCard);raceTray.CancelPendingSelections();Check(!raceTray.SelectionWasWithdrawn(viewToken),"view or scene cancellation never rewrites captured user selection intent");if(!raceTray.SelectionWasWithdrawn(viewToken))raceActor.CharacterClass.RoundAbilityCards.Add(raceModel);raceTray.CompletePendingSelection(raceCard,viewToken);raceTray.SyncFromGameState(raceHand,raceFactory);Check(raceTray.At(0)==raceCard,"old actor native intent still projects correctly after view returns");
Console.WriteLine("Actual pending projection: "+assertions+" assertions passed.");
